// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 blockNum, uint256 ts, address actor) public {
        vm.assume(actor != address(c) && actor != address(this));
        blockNum = bound(blockNum, 1, type(uint64).max);
        ts = bound(ts, 1, type(uint64).max);
        vm.roll(blockNum);
        vm.warp(ts);

        vm.deal(actor, 10 ether);
        uint256 before = address(c).balance;

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        uint256 afterBal = address(c).balance;
        // General rule: any payout (balance decrease) may only occur when
        // block.number % 15 == 0. The mutant pays out whenever the block is
        // NOT a multiple of 15, violating this on such blocks.
        assertTrue(
            (afterBal < before) == (blockNum % 15 == 0),
            "payout must occur exactly on multiples of 15"
        );
    }
}
